// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(address to, uint256 fundAmount) public {
        vm.assume(to != address(0));
        fundAmount = bound(fundAmount, 1, 1000 ether);

        address creator = address(this);

        vm.deal(to, fundAmount);

        vm.deal(creator, fundAmount);
        vm.prank(creator);
        c.deposit{value: fundAmount}();

        uint256 preBalance = address(c).balance;
        require(preBalance > 0, "pre-condition: contract must have funds");

        vm.prank(creator);
        c.migrateTo(to);

        assertTrue(address(c).balance == 0);
    }
}
